cd /tmp/fceval-i3-t1-raan43e4/work; firecrawl interact --timeout 300 -o .firecrawl/results.txt --code '
const out=[];
for (const dz of ["10001","60601","33101","98101","96813"]) for (const p of ["2","6"]) {
  const u=`https://postcalc.usps.com/Calculator/MailServices?country=0&ccode=US&oz=94107&omil=False&dz=${dz}&dmil=False&retail=False&mdt=10%2F17%2F2026&mdz=15%3A59&m=6&hscode=False&p=${p}&o=0`;
  await page.goto(u,{waitUntil:"networkidle"}); await page.waitForTimeout(1500);
  const t=await page.innerText("body");
  const i=t.indexOf("Mail Services"); const j=t.indexOf("Media Mail");
  out.push("#### "+u+"\n"+t.slice(i, j>0?j:i+2500));
}
console.log(out.join("\n\n"));
'; grep -n -E "^####|^Package|^from|^Priority Mail®$|^USPS Ground|Normal Delivery" .firecrawl/results.txt | head -120

